use settlement_gate::*;

fn reference(b: u64, a: u64, f: u64) -> Option<u64> {
    let s = a as u128 + f as u128;
    let gross = (s + 9_999) / 10_000;
    let net = gross - gross / 10;
    let total = a as u128 + net;
    if total <= b as u128 { Some(total as u64) } else { None }
}

fn check(b: u64, a: u64, f: u64) {
    let got = authorize(b, a, f).map(|x| x.total_debit);
    assert_eq!(got, reference(b, a, f), "b={} a={} f={}", b, a, f);
}

fn ref_total(a: u64, f: u64) -> u128 {
    let s = a as u128 + f as u128;
    let gross = (s + 9_999) / 10_000;
    a as u128 + gross - gross / 10
}

fn balances(a: u64, f: u64) -> Vec<u64> {
    let t = ref_total(a, f);
    let mut v = vec![0u64, 1, u64::MAX, u64::MAX - 1];
    for d in [-2i128, -1, 0, 1, 2] {
        let x = t as i128 + d;
        if x >= 0 && x <= u64::MAX as i128 { v.push(x as u64); }
    }
    v
}

#[test]
fn edges() {
    let mut vals: Vec<u64> = vec![];
    let bases: [u64; 8] = [0, 10_000, 1 << 32, 1 << 63, u64::MAX, u64::MAX - 9_999, u64::MAX - 1_616, 18_446_744_073_709_550_000];
    for &bv in &bases {
        for d in 0..20_002u64.min(40) {
            vals.push(bv.wrapping_add(d));
            vals.push(bv.wrapping_sub(d));
        }
    }
    for k in [8_383u64, 8_384, 8_385, 1_615, 1_616, 1_617, 9_998, 9_999, 10_001] {
        vals.push(k); vals.push(u64::MAX - k); vals.push(u64::MAX - k + 1);
    }
    vals.sort(); vals.dedup();
    for &a in &vals { for &f in &vals { for b in balances(a, f) { check(b, a, f); } } }
}

#[test]
fn random() {
    let mut s: u64 = 0x9E3779B97F4A7C15;
    let mut next = || { s ^= s << 13; s ^= s >> 7; s ^= s << 17; s };
    for i in 0..3_000_000u64 {
        let mut a = next();
        let mut f = next();
        match i % 4 { 1 => a %= 100_000, 2 => f = u64::MAX - (f % 100_000), 3 => a = u64::MAX - (a % 1_000_000), _ => {} }
        for b in balances(a, f) { check(b, a, f); }
        let rb = next();
        check(rb, a, f);
    }
}
